item.description:
Get all shows for a movie (grouped by date). Returns data like:
{
  "success": true,
  "data": {
    "movie": { id, title, genre, duration, rating, posterUrl, language },
    "shows": {
      "byDate": {
        "2025-12-30": [ { id, time, hall, totalSeats, availableSeats, price, priceFormatted, status } ],
        "2025-12-31": [ ... ]
      },
      "totalShows": 6,
      "availableDates": [ "2025-12-30", "2025-12-31" ]
    },
    "requestedDate": "all_upcoming"
  },
  "timestamp": "2025-12-30T..."
}
